// Chunk 35: a screenshot of /agent showing the observer's output — one dry-run
// Greenhouse job with its "Fields" drawer open (the numbered field list and the
// page screenshot). Like scripts/e2e-agent.mjs it does NOT touch the database:
// it mocks the /api/agent/* GET routes with a fictional job whose `observer`
// payload and `screenshot_url` come from scripts/.agent-observer-sample/
// (generated by `python scripts/agent_observer_sample.py` against the Greenhouse
// test fixture). A throwaway account only lets the auth middleware render the
// page; it is removed at the end. No model call, no writes beyond the test user.
//
//   python scripts/agent_observer_sample.py          # once, to make the sample
//   npx next start -p 3100
//   PLAYWRIGHT_PATH=<...>/node_modules/playwright/index.mjs node scripts/e2e-agent-observer.mjs
//
// Writes 08-agent-observer-greenhouse.png to OUT.
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

const BASE = process.env.SMOKE_BASE || "http://localhost:3100";
const OUT =
  process.env.OUT ||
  path.resolve("../jobhuntz-audit/2026-11-23/screenshots/08-agent-observer-greenhouse.png");
const SAMPLE = path.resolve("scripts/.agent-observer-sample");

const observer = JSON.parse(fs.readFileSync(path.join(SAMPLE, "observer.json"), "utf8"));
const screenshotUrl = fs.readFileSync(path.join(SAMPLE, "page.datauri.txt"), "utf8").trim();

const env = Object.fromEntries(
  fs
    .readFileSync(".env.local", "utf8")
    .split(/\r?\n/)
    .filter((l) => /^[A-Z_]+=/.test(l))
    .map((l) => [l.slice(0, l.indexOf("=")), l.slice(l.indexOf("=") + 1).trim()])
);
const SB = env.NEXT_PUBLIC_SUPABASE_URL,
  PUB = env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
  SECRET = env.SUPABASE_SECRET_KEY;
const REF = new URL(SB).hostname.split(".")[0];
const admin = { apikey: SECRET, Authorization: `Bearer ${SECRET}`, "Content-Type": "application/json" };
if (!process.env.PLAYWRIGHT_PATH)
  throw new Error("Set PLAYWRIGHT_PATH to a playwright index.mjs (it is not a dependency of this project).");
const { chromium } = await import(pathToFileURL(process.env.PLAYWRIGHT_PATH).href);

const iso = (minsAgo) => new Date(Date.now() - minsAgo * 60_000).toISOString();

const JOBS = [
  {
    id: "obs1",
    job_url: "https://boards.greenhouse.io/acmerobotics/jobs/4100777",
    company: "Acme Robotics",
    role: "Software Engineer",
    ats: "greenhouse",
    status: "dry_run_done",
    mode: "dry_run",
    attempts: 1,
    last_error: null,
    confirmation_url: null,
    screenshot_path: "u/obs1/page.png",
    screenshot_url: screenshotUrl,
    observer,
    created_at: iso(5),
    last_event: { ts: iso(1), level: "info", step: "observed", message: `Read the application form: ${observer.field_count} fields.` },
  },
];
const DEVICES = [{ id: "d1", name: "My PC", last_seen_at: iso(1), revoked: false, created_at: iso(300) }];

const email = `agent-obs-${Date.now()}@example.com`,
  password = `Pw-${Math.random().toString(36).slice(2)}-A1!`;
const created = await (
  await fetch(`${SB}/auth/v1/admin/users`, {
    method: "POST",
    headers: admin,
    body: JSON.stringify({ email, password, email_confirm: true }),
  })
).json();
let browser;
try {
  const session = await (
    await fetch(`${SB}/auth/v1/token?grant_type=password`, {
      method: "POST",
      headers: { apikey: PUB, "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    })
  ).json();
  const cookieValue = "base64-" + Buffer.from(JSON.stringify(session)).toString("base64url");

  browser = await chromium.launch({ channel: "msedge" });
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 1800 }, timezoneId: "Europe/London" });
  await ctx.addCookies([{ name: `sb-${REF}-auth-token`, value: cookieValue, url: BASE }]);

  await ctx.route("**/api/agent/jobs", (route) => {
    if (route.request().method() === "GET") return route.fulfill({ json: { jobs: JOBS } });
    return route.fulfill({ json: { queued: [], queuedCount: 0, duplicates: [], rejected: [] } });
  });
  await ctx.route("**/api/agent/devices", (route) => route.fulfill({ json: { devices: DEVICES } }));

  const page = await ctx.newPage();
  await page.goto(`${BASE}/agent`, { waitUntil: "load" });
  await page.locator("[data-job-row]").first().waitFor({ timeout: 30000 });
  await page.locator("[data-fields-toggle]").first().click();
  await page.locator("[data-fields-row]").waitFor({ timeout: 30000 });
  await page.waitForTimeout(500);

  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  await page.screenshot({ path: OUT, fullPage: true });
  console.log("PASS wrote screenshot:", OUT);
  console.log("PASS fields shown:", await page.locator("[data-fields-drawer] [data-field-index]").count());
} finally {
  if (browser) await browser.close();
  await fetch(`${SB}/auth/v1/admin/users/${created.id}`, { method: "DELETE", headers: admin }).catch(() => {});
}
